/**
 * CSV encoding (RFC 4180) with spreadsheet formula-injection protection.
 *
 * A cell that a spreadsheet would treat as a formula (starts with = + - @, or a tab/CR, optionally after spaces)
 * is prefixed with an apostrophe so it displays as text. The apostrophe is removed again on import, so exported
 * files round-trip. Only free-text columns are sanitised; amount and date columns are generated by us.
 */

/**
 * What a spreadsheet could read as a formula: = + - @ (optionally after spaces/tabs/CR), or a leading tab/CR.
 * Leading apostrophes are skipped when testing, so a value that already begins with ' + formula text is also
 * protected. That keeps the encoding lossless: restoreFormula(neutraliseFormula(x)) === x for every x.
 */
const FORMULA_START = /^'*(?:[ \t\r]*[=+\-@]|[\t\r])/;

export function neutraliseFormula(value: string): string {
  return FORMULA_START.test(value) ? `'${value}` : value;
}

/** Inverse of neutraliseFormula, applied to imported text: "'=1+1" -> "=1+1". Leaves ordinary apostrophes alone. */
export function restoreFormula(value: string): string {
  return value.startsWith("'") && FORMULA_START.test(value.slice(1)) ? value.slice(1) : value;
}

export function escapeField(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

/** Builds a CSV document. `text` marks which columns hold free text (and therefore get formula protection). */
export function toCsv(headers: readonly string[], rows: readonly (readonly string[])[], text: ReadonlySet<number>): string {
  const line = (cells: readonly string[]) => cells.map((c, i) => escapeField(text.has(i) ? neutraliseFormula(c) : c)).join(",");
  return [line(headers), ...rows.map(line)].join("\r\n") + "\r\n";
}
